import json
import os
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler

logger = BackgroundLogger.Instance()


def load_json_file(resource_file_name, testline_dir=''):
    config = ConfigHandler.get_config()
    dict = {}
    resource_files = [os.path.join(config['common_resources_path'], resource_file_name),
                      os.path.join(config['feature_resources_path'], resource_file_name)]
    if testline_dir != '':
        resource_files.append(os.path.join(testline_dir, resource_file_name))

    for resource_file in resource_files:
        if os.path.exists(resource_file):
            with open(resource_file, "r") as file_handle:
                dict.update(json.load(file_handle))
    return dict


def get_resource_file(resource_file_name, testline_dir=''):
    config = ConfigHandler.get_config()
    resource_files = [os.path.join(config['common_resources_path'], resource_file_name),
                      os.path.join(config['feature_resources_path'], resource_file_name)]

    if testline_dir != '':
        resource_files.append(os.path.join(testline_dir, resource_file_name))
        resource_files.reverse()

    for resource_file in resource_files:
        if os.path.exists(resource_file):
            return resource_file
    return None
